-- Dedicated prototype only. Synthetic PostgreSQL subjects, not Auth tokens.
-- All policy, account, attendance and audit changes roll back.
begin;
do $$
declare c uuid; owner_id uuid; hr_id uuid:=gen_random_uuid(); manager_id uuid:=gen_random_uuid(); staff_id uuid:=gen_random_uuid(); outside_id uuid:=gen_random_uuid();
 hr_email text; manager_email text; staff_email text; outside_email text; manager_person uuid; staff_person uuid;
 original_policy jsonb; policy jsonb; shift_id uuid; parent uuid; snapshot jsonb; change jsonb; original_break jsonb;
begin
 if (select count(*) from public.companies)<>1 or to_regprocedure('public.apply_attendance_calculation_policy(jsonb)') is null then raise exception 'Expected initialized HRIS calculation deployment.';end if;
 select id,companies.owner_id into strict c,owner_id from public.companies;
 hr_email:='qa-calc-hr-'||hr_id||'@example.invalid';manager_email:='qa-calc-manager-'||manager_id||'@example.invalid';staff_email:='qa-calc-staff-'||staff_id||'@example.invalid';outside_email:='qa-calc-outside-'||outside_id||'@example.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(hr_id,hr_email,clock_timestamp()),(manager_id,manager_email,clock_timestamp()),(staff_id,staff_email,clock_timestamp()),(outside_id,outside_email,clock_timestamp());
 perform set_config('request.headers','{"x-hris-leave-contract":"2"}',true);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 perform public.save_company_account(hr_id,hr_email,'hr_generalist',true,null,null);
 perform public.save_company_account(manager_id,manager_email,'manager',true,null,null);
 perform public.save_company_account(staff_id,staff_email,'employee',true,null,null);
 perform public.save_company_account(outside_id,outside_email,'manager',true,null,null);
 select employee_id into manager_person from public.company_members where user_id=manager_id;
 select employee_id into staff_person from public.company_members where user_id=staff_id;
 update public.employees set reports_to=manager_person,joined_on='2020-01-01' where id=staff_person;
 select to_jsonb(p) into original_policy from public.attendance_calculation_policies p where company_id=c;
 policy:=original_policy||jsonb_build_object('expected_revision',original_policy->'revision','late_grace_minutes',7,'undertime_grace_minutes',11,'overtime_min_minutes',35,'overtime_round_minutes',15,'reason','Synthetic rollback calculation rules');
 perform public.save_attendance_calculation_policy(policy);
 begin perform public.save_attendance_calculation_policy(policy);raise exception 'Stale policy accepted';exception when sqlstate 'PT409' then null;end;
 perform set_config('request.jwt.claim.sub',hr_id::text,true);
 begin perform public.save_attendance_calculation_policy(policy);raise exception 'HR changed Administrator rules';exception when insufficient_privilege then null;end;
 shift_id:=public.save_shift_template('{"id":null,"expected_revision":null,"name":"Synthetic rollback calculation shift","days":[1,2,3,4,5,6,7],"start_minute":480,"end_minute":1020,"works_on_holidays":true,"active":true,"break_rules":[]}');
 perform public.assign_shift(jsonb_build_object('employee_id',staff_person,'template_id',shift_id,'expected_template_revision',0,'expected_sequence',0,'effective_on','2026-01-01','expected_timezone',(select timezone from public.companies where id=c),'reason','Synthetic rollback calculation schedule'));
 parent:=public.correct_attendance(jsonb_build_object('attendance_id',null,'employee_id',staff_person,'work_date','2026-01-06','checked_in_at','2026-01-06T00:17:00Z','checked_out_at','2026-01-06T10:47:00Z','expected_revision',null,'reason','Synthetic rollback calculation attendance'));
 select calculation_snapshot into snapshot from public.attendance where id=parent;
 assert snapshot->'policy'->>'late_grace_minutes'='7' and snapshot->>'window_status'='ready' and (snapshot->>'scheduled_workday')::boolean,'New attendance policy/calendar snapshot incorrect';
 assert (snapshot->>'planned_start')::timestamptz='2026-01-06T00:00:00Z'::timestamptz and (snapshot->>'planned_end')::timestamptz='2026-01-06T09:00:00Z'::timestamptz,'Saved UTC schedule bounds incorrect';
 perform public.manage_attendance_break('record',jsonb_build_object('attendance_id',parent,'expected_parent_revision',0,'name','Synthetic outside unpaid break','paid',false,'started_at','2026-01-06T09:15:00Z','ended_at','2026-01-06T09:30:00Z','reason','Synthetic rollback outside break'));
 select to_jsonb(b) into original_break from public.attendance_breaks b where attendance_id=parent;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 select to_jsonb(p) into policy from public.attendance_calculation_policies p where company_id=c;
 policy:=policy||jsonb_build_object('expected_revision',policy->'revision','late_grace_minutes',14,'reason','Synthetic rollback revised calculation grace');perform public.save_attendance_calculation_policy(policy);
 assert (select calculation_snapshot=snapshot from public.attendance where id=parent),'Policy edit rewrote historical attendance';
 change:=jsonb_build_object('attendance_id',parent,'expected_revision',0,'expected_policy_revision',(policy->>'revision')::bigint+1,'reason','Synthetic rollback explicit current-rule review');
 begin perform public.apply_attendance_calculation_policy(change||'{"expected_revision":99}');raise exception 'Stale parent accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.apply_attendance_calculation_policy(change||'{"expected_policy_revision":99}');raise exception 'Stale current policy accepted';exception when sqlstate 'PT409' then null;end;
 perform set_config('request.jwt.claim.sub',hr_id::text,true);perform public.apply_attendance_calculation_policy(change||jsonb_build_object('actor_id',outside_id,'calculation_snapshot','{"forged":true}'::jsonb));
 assert (select revision=1 and calculation_snapshot->'policy'->>'late_grace_minutes'='14' and checked_in_at='2026-01-06T00:17:00Z'::timestamptz and checked_out_at='2026-01-06T10:47:00Z'::timestamptz from public.attendance where id=parent),'Explicit rule application changed attendance or did not advance revision';
 assert (select to_jsonb(b)=original_break from public.attendance_breaks b where attendance_id=parent),'Rule application changed recorded breaks';
 assert (select actor_id=hr_id and actor_role='hr_generalist' and before_snapshot=snapshot and after_snapshot->'policy'->>'late_grace_minutes'='14' from public.attendance_calculation_events where attendance_id=parent),'Protected rule application actor/history incorrect';
 begin update public.attendance set calculation_snapshot='{"version":1,"forged":true}' where id=parent;raise exception 'Direct saved-policy change allowed';exception when insufficient_privilege then null;end;
 begin delete from public.attendance_calculation_events where attendance_id=parent;raise exception 'Calculation history deletion allowed';exception when insufficient_privilege then null;end;
 begin update public.attendance_calculation_policies set late_grace_minutes=99 where company_id=c;raise exception 'Direct company policy change allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);
 assert exists(select 1 from public.attendance where id=parent and calculation_snapshot is not null),'Manager cannot read direct-report saved calculations';
 assert exists(select 1 from public.attendance_calculation_policies where company_id=c),'Manager cannot read company rule summary';
 assert not exists(select 1 from public.attendance_calculation_events),'Manager read HR record rule reasons';
 assert not exists(select 1 from public.attendance_calculation_policy_events),'Manager read private company policy reasons';
 begin perform public.apply_attendance_calculation_policy(change);raise exception 'Manager applied team rules';exception when insufficient_privilege then null;end;
 begin perform public.save_attendance_calculation_policy(policy);raise exception 'Manager changed company rules';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outside_id::text,true);assert not exists(select 1 from public.attendance where id=parent),'Unrelated Manager read employee snapshot';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 assert exists(select 1 from public.attendance where id=parent),'Employee cannot read own future-portal snapshot';
 assert not exists(select 1 from public.attendance_calculation_policies),'Employee received desktop policy management data';
 begin perform public.apply_attendance_calculation_policy(change);raise exception 'Employee applied policy';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform public.save_company_account(hr_id,hr_email,'hr_generalist',false,null,null);
 perform set_config('request.jwt.claim.sub',hr_id::text,true);assert not exists(select 1 from public.attendance_calculation_policies),'Disabled HR read policies';
 begin perform public.apply_attendance_calculation_policy(change);raise exception 'Disabled HR applied rules';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';
 begin perform * from public.attendance_calculation_policies;raise exception 'Anonymous rule read allowed';exception when insufficient_privilege then null;end;
 begin perform public.save_attendance_calculation_policy(policy);raise exception 'Anonymous policy write allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 assert not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef),'Public definer exposed';
 assert (select count(*)=3 from pg_class t join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname in ('attendance_calculation_policies','attendance_calculation_policy_events','attendance_calculation_events') and t.relrowsecurity),'Calculation RLS missing';
end;
$$;
rollback;
